name: Flaky Monitor Report

on:
  workflow_run:
    workflows: ["CI"]
    types:
      - completed

permissions:
  contents: read
  actions: read
  pull-requests: write

jobs:
  persist-report:
    runs-on: ubuntu-latest
    if: ${{ github.event.workflow_run.conclusion == 'success' || github.event.workflow_run.conclusion == 'failure' }}
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Download test results artifact
        uses: actions/download-artifact@v4
        with:
          name: test-results
          path: test-results
          run-id: ${{ github.event.workflow_run.id }}
          github-token: ${{ secrets.GITHUB_TOKEN }}

      - name: Download flaky history artifact
        uses: actions/download-artifact@v4
        with:
          name: flaky-history
          path: flaky-history
          github-token: ${{ secrets.GITHUB_TOKEN }}
        continue-on-error: true

      - name: Generate and persist flaky report
        run: |
          # Create history directory if it doesn't exist
          mkdir -p flaky-history

          # Initialize history file if empty
          if [ ! -f flaky-history/flaky-tests.json ]; then
            echo '{}' > flaky-history/flaky-tests.json
          fi

          # Process test results and update flaky history
          # This script would typically parse JUnit XML or similar test output
          # and merge with historical data to identify flaky tests
          python3 - << 'EOF'
import json
import os
import glob
import xml.etree.ElementTree as ET
from datetime import datetime

def parse_junit_results(results_dir):
    """Parse JUnit XML files to extract test results."""
    test_results = {}
    for xml_file in glob.glob(os.path.join(results_dir, "**/*.xml"), recursive=True):
        try:
            tree = ET.parse(xml_file)
            root = tree.getroot()

            # Handle different JUnit XML structures
            for suite in root.iter('testsuite'):
                for test_case in suite.iter('testcase'):
                    name = test_case.get('name')
                    classname = test_case.get('classname', '')
                    full_name = f"{classname}.{name}" if classname else name

                    failure = test_case.find('failure')
                    error = test_case.find('error')
                    skipped = test_case.find('skipped')

                    status = 'passed'
                    if failure is not None:
                        status = 'failed'
                    elif error is not None:
                        status = 'error'
                    elif skipped is not None:
                        status = 'skipped'

                    if full_name not in test_results:
                        test_results[full_name] = {
                            'total_runs': 0,
                            'failures': 0,
                            'last_status': status,
                            'last_run': datetime.now().isoformat()
                        }

                    test_results[full_name]['total_runs'] += 1
                    if status in ['failed', 'error']:
                        test_results[full_name]['failures'] += 1
                    test_results[full_name]['last_status'] = status
                    test_results[full_name]['last_run'] = datetime.now().isoformat()
        except Exception as e:
            print(f"Error parsing {xml_file}: {e}")

    return test_results

def identify_flaky_tests(test_results, threshold=0.3):
    """Identify tests that are flaky based on failure rate."""
    flaky_tests = {}
    for test_name, data in test_results.items():
        if data['total_runs'] > 1:
            failure_rate = data['failures'] / data['total_runs']
            if failure_rate > threshold:
                flaky_tests[test_name] = {
                    **data,
                    'failure_rate': failure_rate
                }
    return flaky_tests

# Main execution
results_dir = 'test-results'
history_file = 'flaky-history/flaky-tests.json'

# Load existing history
try:
    with open(history_file, 'r') as f:
        history = json.load(f)
except (FileNotFoundError, json.JSONDecodeError):
    history = {}

# Parse current test results
current_results = parse_junit_results(results_dir)

# Merge with history
for test_name, data in current_results.items():
    if test_name in history:
        # Update existing test history
        history[test_name]['total_runs'] += data['total_runs']
        history[test_name]['failures'] += data['failures']
        history[test_name]['last_status'] = data['last_status']
        history[test_name]['last_run'] = data['last_run']
    else:
        # Add new test to history
        history[test_name] = data

# Identify flaky tests
flaky_tests = identify_flaky_tests(history)

# Save updated history
with open(history_file, 'w') as f:
    json.dump(history, f, indent=2)

# Save flaky tests report
with open('flaky-history/flaky-report.json', 'w') as f:
    json.dump(flaky_tests, f, indent=2)

print(f"Found {len(flaky_tests)} flaky tests out of {len(history)} total tests")
EOF

      - name: Upload flaky history artifact
        uses: actions/upload-artifact@v4
        with:
          name: flaky-history
          path: flaky-history/
          retention-days: 30

      - name: Comment on PR with flaky test report
        if: ${{ github.event.workflow_run.pull_requests != null && github.event.workflow_run.pull_requests.length > 0 }}
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const fs = require('fs');
            const flakyReport = JSON.parse(fs.readFileSync('flaky-history/flaky-report.json', 'utf8'));

            if (Object.keys(flakyReport).length === 0) {
              console.log('No flaky tests found');
              return;
            }

            let comment = '## 🎭 Flaky Test Report\n\n';
            comment += `Found ${Object.keys(flakyReport).length} flaky tests:\n\n`;
            comment += '| Test Name | Failure Rate | Total Runs | Failures |\n';
            comment += '|-----------|-------------|------------|----------|\n';

            for (const [testName, data] of Object.entries(flakyReport)) {
              const failureRate = (data.failure_rate * 100).toFixed(1);
              comment += `| ${testName} | ${failureRate}% | ${data.total_runs} | ${data.failures} |\n`;
            }

            comment += '\n> ⚠️ Tests with failure rate > 30% are considered flaky';

            const prNumber = context.payload.workflow_run.pull_requests[0].number;

            await github.rest.issues.createComment({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: prNumber,
              body: comment
            });
